# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ALLAH\'IN (CC) ZÂTÎ VE SÜBÛTÎ SIFATLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ZÂTÎ (SELBÎ / TENZÎHÎ) SIFATLAR (6)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Vücûd: Var olması; varlığının zorunlu olması</text>\n  <text x="34" y="108" font-size="11" fill="#1e3a8a">• Kıdem: Ezelî olması; varlığının başlangıcı olmaması</text>\n  <text x="34" y="128" font-size="11" fill="#1e3a8a">• Bekâ: Ebedî olması; varlığının sonu olmaması</text>\n  <text x="34" y="148" font-size="11" fill="#1e3a8a">• Vahdâniyyet: Zâtında, sıfatlarında ve fiillerinde bir olması</text>\n  <text x="34" y="168" font-size="11" fill="#1e3a8a">• Muhâlefetün li\'l-havâdis: Sonradan olanlara benzememesi</text>\n  <text x="34" y="188" font-size="11" fill="#1e3a8a">• Kıyâm bi-nefsihî: Var olmak için hiçbir şeye muhtaç olmaması</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SÜBÛTÎ SIFATLAR (8)</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• Hayat: Diri ve canlı olması, hayatın kaynağı olması</text>\n  <text x="370" y="108" font-size="11" fill="#14532d">• İlim: Gizli ve açık, geçmiş ve gelecek her şeyi bilmesi</text>\n  <text x="370" y="128" font-size="11" fill="#14532d">• Semî ve Basar: Her şeyi işitmesi ve görmesi</text>\n  <text x="370" y="148" font-size="11" fill="#14532d">• İrade: Dilemesi, tercih etmesi ve belirlemesi</text>\n  <text x="370" y="168" font-size="11" fill="#14532d">• Kudret: Sonsuz güç ve iktidar sahibi olması</text>\n  <text x="370" y="188" font-size="11" fill="#14532d">• Kelam (Vahiy/Konuşma) ve Tekvin (Yoktan yaratma)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«O\'nun benzeri hiçbir şey yoktur. O, işitendir, görendir.» (Şûrâ suresi, 11. ayet)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ESMÂ-İ HÜSNÂ (EN GÜZEL İSİMLER) VE HAŞR SURESİ 22-24. AYETLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">RAHMET, İLİM VE KUDRET İSİMLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#713f12">• Er-Rahmân: Dünyada bütün varlıklara merhamet eden</text>\n  <text x="34" y="110" font-size="11" fill="#713f12">• Er-Rahîm: Ahirette müminlere özel şefkat gösteren</text>\n  <text x="34" y="132" font-size="11" fill="#713f12">• El-Alîm / El-Habîr: Her şeyi hakkıyla bilen / haberdar olan</text>\n  <text x="34" y="154" font-size="11" fill="#713f12">• Er-Rezzâk: Bütün canlıların maddi-manevi rızkını veren</text>\n  <text x="34" y="176" font-size="11" fill="#713f12">• El-Hakîm / El-Adl: Her işi hikmetli olan / mutlak adil</text>\n  <text x="34" y="196" font-size="11" fill="#713f12">• El-Hayy / El-Kayyûm: Diri olan / kâinatı ayakta tutan</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">HAŞR SURESİ 22-24. AYETLERDEKİ İSİMLER</text>\n  <text x="370" y="88" font-size="11" fill="#581c87">• El-Melik: Mülkün gerçek sahibi ve hükümdarı</text>\n  <text x="370" y="110" font-size="11" fill="#581c87">• El-Kuddûs: Her türlü eksiklik ve kusurdan münezzeh</text>\n  <text x="370" y="132" font-size="11" fill="#581c87">• Es-Selâm / El-Mü\'min: Esenlik veren / güven bahşeden</text>\n  <text x="370" y="154" font-size="11" fill="#581c87">• El-Müheymin: Gözetip koruyan | El-Azîz: Mutlak galip</text>\n  <text x="370" y="176" font-size="11" fill="#581c87">• El-Hâlık: Takdir edip yaratan | El-Bâri\': Uyumlu yaratan</text>\n  <text x="370" y="196" font-size="11" fill="#581c87">• El-Musavvir: Varlıklara en güzel şekli ve sureti veren</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«En güzel isimler (Esmâ-i Hüsnâ) Allah\'ındır. O hâlde O\'na o güzel isimlerle dua edin.» (A\'râf suresi, 180. ayet)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MARİFETULLAH: İSİM VE SIFATLARIN İNSAN HAYATINA YANSIMASI</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Evrendeki Tecelliyi Okuma</text>\n  <text x="34" y="88" font-size="10.8" fill="#1e3a8a">• Kâinattaki her varlık Allah\'ın</text>\n  <text x="42" y="104" font-size="10.5" fill="#1e3a8a">isim ve sıfatlarının tecellisidir.</text>\n  <text x="34" y="128" font-size="10.8" fill="#1e3a8a">• Baharda doğanın dirilişi</text>\n  <text x="42" y="144" font-size="10.5" font-weight="bold" fill="#1d4ed8">El-Muhyî ve El-Hâlık</text>\n  <text x="42" y="160" font-size="10.5" fill="#1e3a8a">isimlerinin açık bir göstergesidir.</text>\n  <text x="34" y="184" font-size="10.8" fill="#1e3a8a">• Marifetullah bilinci gelişir.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Ahlaki Sorumluluk ve İhsan</text>\n  <text x="257" y="88" font-size="10.8" fill="#14532d">• El-Alîm, Es-Semî ve El-Basîr</text>\n  <text x="265" y="104" font-size="10.5" fill="#14532d">olduğunu bilen mümin gizlide</text>\n  <text x="265" y="120" font-size="10.5" fill="#14532d">ve açıkta dürüst davranır.</text>\n  <text x="257" y="144" font-size="10.8" fill="#14532d">• Er-Rahîm, El-Gafûr, El-Kerîm</text>\n  <text x="265" y="160" font-size="10.5" fill="#14532d">isimlerinden ilham alarak</text>\n  <text x="265" y="176" font-size="10.5" font-weight="bold" fill="#15803d">merhametli, affedici ve cömert</text>\n  <text x="265" y="192" font-size="10.5" fill="#14532d">bir karakter inşa eder.</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Dua, Tevekkül ve Huzur</text>\n  <text x="480" y="88" font-size="10.8" fill="#7c2d12">• Dua ederken talebe uygun</text>\n  <text x="488" y="104" font-size="10.5" fill="#7c2d12">Esmâ-i Hüsnâ ile yakarılır:</text>\n  <text x="480" y="126" font-size="10.8" font-weight="bold" fill="#c2410c">• Şifa için → Eş-Şâfî</text>\n  <text x="480" y="144" font-size="10.8" font-weight="bold" fill="#c2410c">• Rızık için → Er-Rezzâk</text>\n  <text x="480" y="162" font-size="10.8" font-weight="bold" fill="#c2410c">• Bağışlanma → El-Gaffâr / Et-Tevvâb</text>\n  <text x="480" y="184" font-size="10.8" fill="#7c2d12">• El-Vekîl ve El-Hafîz bilinci</text>\n  <text x="488" y="198" font-size="10.5" fill="#7c2d12">kalbe güven ve sekînet verir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Allah\'ı (cc) güzel isim ve sıfatlarıyla tanımak (marifetullah), imanı bilinçli ve ahlakı sağlam kılar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
